-- @featherbone-dev-script v1
-- @name      Teardrop Campers demo data (Road Runner Campers)
-- @target    instance
-- @destructive
-- @requires-cleared
-- @rows      181553
-- @anchor    2027-07-05
--
-- Loads a full year of trading history plus the current open order book for the
-- Road Runner Campers / Teardrop Campers demo, built from the ddom demo dataset
-- ("Teardrop Campers"). Generated 2026-10-24.
--
-- DEVELOPER USE ONLY. Run it only on a database that has just been emptied with
-- scripts/dev/clear-instance-data.sql. It refuses to run otherwise.
--
--   npm run dev:load -- --clear --script scripts/dev/demo-data/teardrop-campers.sql --db demo
--
-- WHAT IT LOADS
--   master data   86 items (13 manufactured, 72 purchased, 1 service), bills of
--                 material, routings, 8 suppliers, 9 customers, 8 employees, one
--                 site (WH1), units, categories, terms, ship methods, currencies.
--   history       2025-12-25 .. 2027-01-28 in ddom's dates, all closed:
--                   641 sales orders / 1,127 lines, each shipped and invoiced
--                   4,817 work orders / 63,646 requirements, all received
--                   379 purchase orders / 3,628 lines, all received
--                   73,285 inventory transactions with running balances
--   open book     as at 2027-02-01 in ddom's dates ("today" for the data set):
--                   174 sales orders / 231 lines, due to 2027-06-02
--                   69 purchase orders due 2027-01-27 .. 2027-02-19
--                   185 work orders / 2,476 requirements, released within
--                   19 days of the anchor
--                   1,096 allocations
--   inventory     80 inventory records; on-hand equals the ddom demo's
--                 Inventories.xlsx position exactly for all 68 stocked items.
--
-- WORK ORDER STRUCTURE
-- Built the way make/do-explode-work-order.js builds it, not copied from ddom's
-- own order list (which carries kit orders that the explosion would never make):
--   * A kit or phantom (item type K or P) is spliced out of the parent's bill of
--     material and replaced, in place and recursively, by its own components with
--     quantityPer multiplied through. No kit is ever a requirement or an order.
--   * A requirement whose item has an inventory record and planning policy "M" is
--     made to order: it gets a child work order, numbered in one flat counter
--     across the group (W-nnnnn-1 for the parent, -2, -3 ... for the rest), with a
--     firm allocation from the child order to the parent requirement. An order
--     that spawns no child keeps its plain number.
--   * required = (quantityPer * planned + fixedQuantity) * ratio, rounded up for a
--     non-fractional item.
--   * A manufactured item whose policy is not "M" is replenished to stock instead:
--     2-GALLEY-ASSY is the one such item here and gets its own weekly lot orders
--     with no sales order link.
--   * Operations are scheduled forward from the order's start date, which is what
--     the Timeline tab draws. Each operation's lead time is its run time (by run
--     unit) plus setup, queue, wait and move, plus (service lead time + 1) days;
--     planned start and end chain operation to operation from UTC midnight of the
--     start date. Start to due is the larger of the item's lead time and what the
--     schedule needs, and operationEndDate is where the schedule actually lands.
--     An item with no routing gets no operations and so no timeline, which is how
--     the master data stands: 2-REAR-HATCH-ASSY is the one such item here.
--   * Open demand is allocated as plan/do-create-allocations.js allocates it,
--     inventory first then open purchase order lines, skipping any item whose
--     planning policy is "R".
--
-- DATES AND THE ANCHOR
-- The file carries ddom's own dates, where "today" is 2027-02-01, and shifts
-- them on the way in. Out of the box the anchor is 2027-07-05 -- mid-2027, so the
-- six months January to June are complete in the books, which is the shape a
-- historical summary wants. Override it per load:
--
--   PGOPTIONS="-c featherbone.load_anchor=2028-01-03" psql -d demo -f <this file>
--   npm run dev:load -- --anchor 2028-01-03 --script ... --db demo
--
-- Setting it to 2027-02-01 gives ddom's dates unshifted. Every date and
-- timestamp moves together, so the history, the open book, the operation schedule
-- and the inventory position stay consistent with each other. The default shift is
-- a whole number of weeks, which keeps the weekly batching on the same weekday; a
-- shift that is not says so when it loads.
--
-- At the default anchor: history 2026-05-28 .. 2027-07-01, open sales orders to
-- 2027-11-03, and "today" 2027-07-05. The opening balance on 2026-05-28 is sized so
-- that no item ever goes negative and the closing position matches ddom exactly.
--
-- ONE THING TO KNOW ABOUT THE DEFAULT ANCHOR. ddom's demand is seasonal the way a
-- camper maker's is: in its own dates it peaks in June (154 order lines) and
-- bottoms out in December (40). A 154-day shift moves that peak to November
-- and the trough to May, so at the default anchor the business appears to sell
-- most of its campers going into winter. Only a shift of a whole number of years
-- keeps the seasons where they belong, and ddom's history ends in January, so no
-- such shift puts "today" in the middle of a year -- the two cannot both be had.
-- If the seasons matter more than the mid-year position for what you are showing,
-- load with --anchor 2028-02-01 instead: the same data exactly twelve months on,
-- seasons intact, with "today" in early February.
--
-- Synthesised, because ddom's demand history does not record it: which customer
-- bought each historical order, and the purchase orders that supplied the
-- components. ddom's delivery dates, quantities, items, bills of material and
-- closing inventory are its own.

\set ON_ERROR_STOP on
BEGIN;
SET LOCAL lock_timeout = '10s';

DO $guard$
DECLARE v_kind text; v_n bigint; v_c bigint; v_missing text; v_t text; v_first text;
BEGIN
    IF to_regclass('public."$db"') IS NULL THEN
        RAISE EXCEPTION 'Not a Featherbone database ("$db" missing).';
    END IF;
    SELECT kind INTO v_kind FROM public."$db" LIMIT 1;
    IF v_kind IS DISTINCT FROM 'instance' THEN
        RAISE EXCEPTION 'Database % is kind "%", not "instance".', current_database(), coalesce(v_kind,'(none)');
    END IF;
    SELECT string_agg(x, ', ') INTO v_missing FROM (
        SELECT x FROM unnest(ARRAY['Product','SalesOrder','WorkOrder','PurchaseOrder','Inventory','Customer','Supplier']) x
        WHERE NOT EXISTS (SELECT 1 FROM public.feather f WHERE f.name = x AND NOT f.is_deleted)) z;
    IF v_missing IS NOT NULL THEN
        RAISE EXCEPTION 'SupplyChain is not deployed here - missing feather(s): %. Deploy the package first.', v_missing;
    END IF;
    v_n := 0;
    FOREACH v_t IN ARRAY ARRAY['address', 'item_unit', 'item_unit_conversion', 'item_group', 'kind', 'item_category', 'customer_category', 'terms', 'ship_method', 'labor_resource', 'machine_resource', 'site', 'contact', 'employee', 'product', 'service', 'product_bill_of_material_item', 'product_operation', 'item_site', 'item_supplier', 'item_supplier_price', 'item_conversion', 'proposed_cost', 'supplier', 'customer', 'sales_order', 'sales_order_line', 'sales_order_shipment', 'sales_order_shipment_line', 'shipment_invoice', 'invoice_line', 'sales_history', 'work_order', 'work_order_requirement', 'work_order_operation', 'work_order_receipt', 'purchase_order', 'purchase_order_line', 'purchase_order_receipt', 'purchase_order_receipt_line', 'inventory_adjustment', 'inventory_transaction', 'inventory', 'allocation'] LOOP
        EXECUTE format('SELECT count(*) FROM ONLY %I', v_t) INTO v_c;
        IF v_c > 0 THEN
            v_n := v_n + v_c;
            v_first := coalesce(v_first || ', ', '') || v_t || ' (' || v_c || ')';
        END IF;
    END LOOP;
    IF v_n > 0 THEN
        RAISE EXCEPTION 'This database still holds % application record(s) in: %. Empty it with scripts/dev/clear-instance-data.sql first (a partial clear leaves duplicates).', v_n, v_first;
    END IF;
END
$guard$;

CREATE TEMP TABLE _fbbase(b bigint, shift integer) ON COMMIT DROP;
SELECT nextval('object__pk_seq'),
       (coalesce(
            nullif(current_setting('featherbone.load_anchor', true), ''),
            '2027-07-05'
        )::date - DATE '2027-02-01');
SELECT setval('object__pk_seq', (SELECT b FROM _fbbase) + 181553);

DO $anchor$
DECLARE v_shift integer;
BEGIN
    SELECT shift INTO v_shift FROM _fbbase;
    RAISE NOTICE 'Loading with "today" at % (ddom''s own dates shifted by % days).',
        DATE '2027-02-01' + v_shift, v_shift;
    IF v_shift % 7 <> 0 THEN
        RAISE NOTICE 'That is not a whole number of weeks, so the weekly batching no longer falls on the same weekday.';
    END IF;
END
$anchor$;

CREATE TEMP TABLE s_address (rpk bigint, created timestamptz, "type" text, name text, street text, unit text, city text, state text, postal_code text, country text, phone text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, s."type", s.name, s.street, s.unit, s.city, s.state, s.postal_code, s.country, s.phone FROM s_address s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_honorific (rpk bigint, created timestamptz, title text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.title FROM s_honorific s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY honorific k WHERE k.title IS NOT DISTINCT FROM s.title);

CREATE TEMP TABLE s_country (rpk bigint, created timestamptz, code text, name text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.name FROM s_country s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY country k WHERE k.code IS NOT DISTINCT FROM s.code);

CREATE TEMP TABLE s_state (rpk bigint, created timestamptz, code text, name text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.name FROM s_state s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY state k WHERE k.code IS NOT DISTINCT FROM s.code);

CREATE TEMP TABLE s_currency (rpk bigint, created timestamptz, code text, description text, note text, symbol text, minor_unit integer, is_base boolean, has_display_unit boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.note, s.symbol, s.minor_unit, s.is_base, s.has_display_unit FROM s_currency s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY currency k WHERE k.code IS NOT DISTINCT FROM s.code);

CREATE TEMP TABLE s_currency_unit (rpk bigint, created timestamptz, code text, description text, dimension text, symbol text, minor_unit integer) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.dimension, s.symbol, s.minor_unit FROM s_currency_unit s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY currency_unit k WHERE k.code IS NOT DISTINCT FROM s.code);

CREATE TEMP TABLE s_base_currency (rpk bigint, created timestamptz, _currency_currency_pk text, effective timestamptz) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), (SELECT r._pk FROM ONLY currency r WHERE r.code = s._currency_currency_pk), (s.effective + make_interval(days => b.shift)) FROM s_base_currency s CROSS JOIN _fbbase b
 WHERE NOT EXISTS (SELECT 1 FROM ONLY base_currency k);

CREATE TEMP TABLE s_item_unit (rpk bigint, created timestamptz, code text, description text, dimension text, is_default boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.dimension, s.is_default FROM s_item_unit s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_item_unit_conversion (rpk bigint, created timestamptz, ratio numeric, _from_unit_item_unit_pk bigint, _to_unit_item_unit_pk bigint) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.ratio, (b.b+s._from_unit_item_unit_pk), (b.b+s._to_unit_item_unit_pk) FROM s_item_unit_conversion s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_item_group (rpk bigint, created timestamptz, code text, description text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description FROM s_item_group s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_kind (rpk bigint, created timestamptz, code text, description text, note text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.note FROM s_kind s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_item_category (rpk bigint, created timestamptz, code text, description text, note text, _parent_kind_pk bigint) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.note, (b.b+s._parent_kind_pk) FROM s_item_category s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_customer_category (rpk bigint, created timestamptz, code text, description text, note text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.note FROM s_customer_category s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_terms (rpk bigint, created timestamptz, code text, policy text, net integer, day integer, discount_days integer, discount numeric, deposit_required boolean, deposit_percent numeric, deposit_amount numeric) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.policy, s.net, s.day, s.discount_days, s.discount, s.deposit_required, s.deposit_percent, ROW(s.deposit_amount,'USD',NULL,s.deposit_amount)::mono FROM s_terms s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_ship_method (rpk bigint, created timestamptz, code text, description text, international boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, s.international FROM s_ship_method s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_labor_resource (rpk bigint, created timestamptz, code text, description text, labor_cost numeric) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, ROW(s.labor_cost,'USD',NULL,s.labor_cost)::mono FROM s_labor_resource s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_machine_resource (rpk bigint, created timestamptz, code text, description text, overhead_cost numeric) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, ROW(s.overhead_cost,'USD',NULL,s.overhead_cost)::mono FROM s_machine_resource s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_site (rpk bigint, created timestamptz, code text, description text, _address_address_pk bigint, location_controlled boolean, _bill_to_address_pk bigint) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.code, s.description, (b.b+s._address_address_pk), s.location_controlled, (b.b+s._bill_to_address_pk) FROM s_site s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_contact (rpk bigint, created timestamptz, first_name text, last_name text, full_name text, phone text, phone_type text, email text, email_type text, _address_address_pk bigint, web_site text) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.first_name, s.last_name, s.full_name, s.phone, s.phone_type, s.email, s.email_type, (b.b+s._address_address_pk), s.web_site FROM s_contact s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_employee (rpk bigint, created timestamptz, first_name text, last_name text, full_name text, phone text, phone_type text, email text, email_type text, "number" text, user_account text, is_buyer boolean, is_sales_rep boolean, is_active boolean) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s.first_name, s.last_name, s.full_name, s.phone, s.phone_type, s.email, s.email_type, s."number", s.user_account, s.is_buyer, s.is_sales_rep, s.is_active FROM s_employee s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_product (rpk bigint, created timestamptz, "number" text, description text, _unit_item_unit_pk bigint, _group_item_group_pk bigint, _category_item_category_pk bigint, price numeric, eoq numeric, material_cost numeric, labor_cost numeric, service_cost numeric, overhead_cost numeric, cost numeric, _site_site_pk bigint, trace text, is_fractional boolean, status text, is_sold boolean, weight numeric, "type" text, source text, country_of_origin text, harmonized_tariff_code text, customs_value numeric, "comments" text, long_description text, customs_description text, taxable boolean, revision text, is_container boolean, length numeric, width numeric, height numeric) ON COMMIT DROP;
SELECT b.b+s.rpk, substr(md5('fbtd'||(b.b+s.rpk)::text),1,12), (s.created + make_interval(days => b.shift)), 'admin', (s.created + make_interval(days => b.shift)), 'admin', false, 'admin', substr(md5('etg'||(b.b+s.rpk)::text),1,12), s."number", s.description, (b.b+s._unit_item_unit_pk), (b.b+s._group_item_group_pk), (b.b+s._category_item_category_pk), ROW(s.price,'USD',NULL,s.price)::mono, s.eoq, ROW(s.material_cost,'USD',NULL,s.material_cost)::mono, ROW(s.labor_cost,'USD',NULL,s.labor_cost)::mono, ROW(s.service_cost,'USD',NULL,s.service_cost)::mono, ROW(s.overhead_cost,'USD',NULL,s.overhead_cost)::mono, ROW(s.cost,'USD',NULL,s.cost)::mono, (b.b+s._site_site_pk), s.trace, s.is_fractional, s.status, s.is_sold, s.weight, s."type", s.source, s.country_of_origin, s.harmonized_tariff_code, ROW(s.customs_value,'USD',NULL,s.customs_value)::mono, s."comments", s.long_description, s.customs_description, s.taxable, s.revision, s.is_container, s.length, s.width, s.height FROM s_product s CROSS JOIN _fbbase b;

CREATE TEMP TABLE s_service (rpk bigint, created timestamptz, "number" text, description text, _unit_item_unit_pk bigint, _group_item_group_pk bigint, _category_item_category_pk bigint, price numeric, eoq numeric, material_cost numeric, labor_cost numeric, service_cost numeric, overhead_cost numeric, cost numeric, _site_site_pk bigint, trace text, is_fractional boolean, status text, is_sold boolean, weight numeric, "type" text, source text, country_of_origin text, harmonized_tariff_code text, customs_value numeric, "comments" text, long_description text, customs_description text, taxable boolean) ON COMMIT DROP;
