CREATE TEMP TABLE s_inventory_transaction (rpk bigint, created timestamptz, "number" text, "date" date, _item_item_pk bigint, _site_site_pk bigint, quantity numeric, "comments" text, quantity_before numeric, quantity_after numeric, material_cost numeric, labor_cost numeric, service_cost numeric, overhead_cost numeric, total_cost numeric, reference text, "type" text, document text) ON COMMIT DROP;
